  "<section class=\"tools-page web-page\" data-running=\"⟦0⟧\">\n<div class=\"page-heading\"><div class=\"web-heading-copy\"><h1>网页共享</h1><span id=\"web-status\"></span></div>⟦1⟧</div>\n<div class=\"tools-scroll\"><p id=\"web-error\" class=\"sync-error\" role=\"alert\"></p>⟦2⟧</div></section>": "<section class=\"tools-page web-page\" data-running=\"⟦0⟧\">\n<div class=\"page-heading\"><div class=\"web-heading-copy\"><h1>Web sharing</h1><span id=\"web-status\"></span></div>⟦1⟧</div>\n<div class=\"tools-scroll\"><p id=\"web-error\" class=\"sync-error\" role=\"alert\"></p>⟦2⟧</div></section>",
